/**
 * Test flow for Weekly trigger
 * Tests: Weekly scheduled trigger with day and time configuration
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testWeeklyTrigger = Flow(
    {
        $id: Now.ID['test_weekly_trigger_flow'],
        name: 'Test Weekly Trigger',
        description: 'Tests the Weekly trigger running on specified day and time',
    },
    wfa.trigger(
        trigger.scheduled.weekly,
        { $id: Now.ID['test_weekly_trigger'] },
        {
            day_of_week: 2, // Monday (1=Sunday, 2=Monday, ..., 7=Saturday)
            time: Time(
                {
                    hours: 9,
                    minutes: 0,
                    seconds: 0,
                },
                'UTC'
            ),
        }
    ),
    (_params) => {
        // Log trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_weekly_trigger_log'] },
            {
                log_level: 'info',
                log_message: `Weekly Trigger - Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)
